	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		FulfillmentCenter
	 */
		public FulfillmentCenter createFulfillmentCenter( CreateFulfillmentCenterCommand command ) {

		FulfillmentCenter entity = new FulfillmentCenter();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setFulfillmentCenterId( command.getFulfillmentCenterId() );
            entity.setName( command.getName() );
            entity.setCenterCode( command.getCenterCode() );
            entity.setAddress( command.getAddress() );
            entity.setTimezone( command.getTimezone() );
            entity.setAsActive( command.getAsActive() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of FulfillmentCenter {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateFulfillmentCenterCommand
	 * @return		FulfillmentCenter
	 */
	public FulfillmentCenter updateFulfillmentCenter( UpdateFulfillmentCenterCommand command ) {

		FulfillmentCenter entity = new FulfillmentCenter();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setFulfillmentCenterId( command.getFulfillmentCenterId() );
            entity.setName( command.getName() );
            entity.setCenterCode( command.getCenterCode() );
            entity.setAddress( command.getAddress() );
            entity.setTimezone( command.getTimezone() );
            entity.setAsActive( command.getAsActive() );
            entity.setMerchant( command.getMerchant() );
            entity.setInventoryItems( command.getInventoryItems() );
            entity.setShipments( command.getShipments() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of FulfillmentCenter {0} ", entity.toString() );

		return entity;
	}

